    if (!p) die("out of memory");
    return p;
}

static double dot(int n, const double *a, const double *b) {
    double s = 0.0;
    for (int i = 0; i < n; i++) s += a[i] * b[i];
    return s;
}

static void dcopy(int n, const double *src, double *dst) {
