static void generate_laplacian2d(int n, const char *output) {
    int N = n * n;
    int cap = N * 3;
    Entry *entries = xmalloc((size_t)cap * sizeof(Entry));
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int row = i * n + j;
            entries[count].r = row;
            entries[count].c = row;
            entries[count].v = 4.0;
            count++;
            if (j > 0) {
                int col = i * n + (j - 1);
                entries[count].r = row;
                entries[count].c = col;
                entries[count].v = -1.0;
                count++;
            }
            if (i > 0) {
                int col = (i - 1) * n + j;
                entries[count].r = row;
                entries[count].c = col;
                entries[count].v = -1.0;
                count++;
            }
        }
    }
    qsort(entries, (size_t)count, sizeof(Entry), cmp_entry_rc);
    write_matrix_market(output, N, count, entries);
    free(entries);
}

