    int n = m->n;
    int *adj_ptr, *adj_count, *adj;
    build_adjacency(m, &adj_ptr, &adj_count, &adj);

    int *degree = xcalloc((size_t)n, sizeof(int));
    for (int i = 0; i < n; i++) degree[i] = adj_ptr[i + 1] - adj_ptr[i];

    int *visited = xcalloc((size_t)n, sizeof(int));
    int *order = xmalloc((size_t)n * sizeof(int));
    int order_count = 0;
    int *queue = xmalloc((size_t)n * sizeof(int));
    int qhead = 0, qtail = 0;

    while (order_count < n) {
        int start = -1;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                if (start == -1 || degree[i] < degree[start] ||
                    (degree[i] == degree[start] && i < start)) {
                    start = i;
                }
            }
        }
        if (start == -1) break;
        visited[start] = 1;
        queue[qtail++] = start;
        while (qhead < qtail) {
            int v = queue[qhead++];
            order[order_count++] = v;
            int base = adj_ptr[v];
            int deg = adj_ptr[v + 1] - base;
