                nbrs[b + 1] = key;
            }
            for (int idx = 0; idx < cnt; idx++) {
                int u = nbrs[idx];
                if (!visited[u]) {
                    visited[u] = 1;
                    queue[qtail++] = u;
                }
            }
            free(nbrs);
        }
    }

    for (int i = 0; i < n; i++) perm[order[n - 1 - i]] = i;

