static double *solve_cg(CSRMatrix *A, double *b, Precond *p, int max_it, double tol) {
    int n = A->n;
    double *x = xcalloc((size_t)n, sizeof(double));
    double *r = xmalloc((size_t)n * sizeof(double));
    double *z = xmalloc((size_t)n * sizeof(double));
    double *pvec = xmalloc((size_t)n * sizeof(double));
    double *Ap = xmalloc((size_t)n * sizeof(double));

    spmv(A, x, r);
    for (int i = 0; i < n; i++) r[i] = b[i] - r[i];
    double bnorm = vec_norm2(n, b);
    if (bnorm == 0.0) {
        free(r); free(z); free(pvec); free(Ap);
        return x;
    }

    precond_apply(p, r, z);
    dcopy(n, z, pvec);
    double rz_old = dot(n, r, z);

    for (int it = 0; it < max_it; it++) {
        spmv(A, pvec, Ap);
        double pAp = dot(n, pvec, Ap);
        if (pAp <= 0.0) {
            free(r); free(z); free(pvec); free(Ap);
            die("matrix is not positive definite");
        }
        double alpha = rz_old / pAp;
        for (int i = 0; i < n; i++) {
            x[i] += alpha * pvec[i];
            r[i] -= alpha * Ap[i];
        }
        if (vec_norm2(n, r) <= tol * bnorm) break;

        precond_apply(p, r, z);
        double rz_new = dot(n, r, z);
        if (rz_old == 0.0) {
            free(r); free(z); free(pvec); free(Ap);
            die("CG numerical breakdown");
        }
        double beta = rz_new / rz_old;
        for (int i = 0; i < n; i++) pvec[i] = z[i] + beta * pvec[i];
        rz_old = rz_new;
    }

    free(r); free(z); free(pvec); free(Ap);
    return x;
}

