        double rho_new = dot(n, r0, r);
        if (rho_new == 0.0) {
            free(r); free(r0); free(pvec); free(v); free(s); free(t); free(z);
            die("BiCGSTAB numerical breakdown");
        }
        double beta = (rho_new / rho_old) * (alpha / omega);
        for (int i = 0; i < n; i++) pvec[i] = r[i] + beta * pvec[i];
        rho_old = rho_new;
    }

    free(r); free(r0); free(pvec); free(v); free(s); free(t); free(z);
    return x;
}

static void write_vector(const char *filename, int n, const double *x) {
    FILE *f = stdout;
    if (filename) {
        f = fopen(filename, "w");
        if (!f) die("cannot open output vector file");
    }

    if (fprintf(f, "%d\\n", n) < 0) {
        if (filename) fclose(f);
        die("failed to write vector");
    }
    for (int i = 0; i < n; i++) {
        if (fprintf(f, "%.15g\\n", x[i]) < 0) {
            if (filename) fclose(f);
            die("failed to write vector");
        }
    }

    if (filename) fclose(f);
}

static int parse_int_arg(const char *s) {
    if (!s || !*s) die("missing argument");
    errno = 0;
    char *end;
    long val = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\\0') die("invalid integer argument");
    if (val < INT_MIN || val > INT_MAX) die("integer argument out of range");
    return (int)val;
}

static double parse_double_arg(const char *s) {
    if (!s || !*s) die("missing argument");
    errno = 0;
    char *end;
    double val = strtod(s, &end);
    if (errno != 0 || end == s || *end != '\\0') die("invalid numeric argument");
    return val;
}

static void die_unknown(const char *kind, const char *value) {
    char msg[256];
    snprintf(msg, sizeof(msg), "unknown %s: %s", kind, value);
    die(msg);
}

